{"content":"// Package shapes provides basic 2D shapes.
package shapes

import (
	"errors"
	"math"
	"strconv"
)

// Shape is a 2D shape.
type Shape interface {
	Area() float64
	Perimeter() float64
}

// Circle is a circle with radius R.
type Circle struct{ R float64 }

func (c Circle) Area() float64  { return math.Pi * c.R * c.R }
func (c Circle) Perimeter() float64 { return 2 * math.Pi * c.R }

func (c Circle) String() string {
	return "Circle(r=" + strconv.FormatFloat(c.R, 'f', -1, 64) + ")"
}

// Rectangle is an axis-aligned rectangle.
type Rectangle struct{ W, H float64 }

func (r Rectangle) Area() float64  { return r.W * r.H }
func (r Rectangle) Perimeter() float64 { return 2 * (r.W + r.H) }

func (r Rectangle) String() string {
	return "Rectangle(" + strconv.FormatFloat(r.W, 'f', -1, 64) + "x" +
		strconv.FormatFloat(r.H, 'f', -1, 64) + ")"
}

// Triangle has side lengths A, B, C.
type Triangle struct{ A, B, C float64 }

// NewTriangle validates the triangle inequality.
func NewTriangle(a, b, c float64) (Triangle, error) {
	if a <= 0 || b <= 0 || c <= 0 || a+b <= c || a+c <= b || b+c <= a {
		return Triangle{}, errors.New("shapes: invalid triangle")
	}
	return Triangle{a, b, c}, nil
}

func (t Triangle) Perimeter() float64 { return t.A + t.B + t.C }

// Area uses Heron's formula.
func (t Triangle) Area() float64 {
	s := t.Perimeter() / 2
	return math.Sqrt(s * (s - t.A) * (s - t.B) * (s - t.C))
}

func (t Triangle) String() string {
	return "Triangle(" + strconv.FormatFloat(t.A, 'f', -1, 64) + "," +
		strconv.FormatFloat(t.B, 'f', -1, 64) + "," +
		strconv.FormatFloat(t.C, 'f', -1, 64) + ")"
}

// TotalArea sums the areas.
func TotalArea(shapes []Shape) float64 {
	sum := 0.0
	for _, s := range shapes {
		sum += s.Area()
	}
	return sum
}

// Largest returns the shape with the greatest area (the first one on ties),
// or false if shapes is empty.
func Largest(shapes []Shape) (Shape, bool) {
	if len(shapes) == 0 {
		return nil, false
	}
	best := shapes[0]
	for _, s := range shapes[1:] {
		if s.Area() > best.Area() {
			best = s
		}
	}
	return best, true
}
